<?php require_once 'includes/db.php'; session_start(); require_once 'includes/functions.php'; $origem=(int)($_POST['origem_id']??0);$destino=(int)($_POST['destino_id']??0);$trans=(int)($_POST['transportador_id']??0);$prods=$_POST['produtos']??[];$qtys=$_POST['quantidades']??[];$data=$_POST['data_frete']??''; if(!$origem||!$destino||$origem===$destino||!$trans||!$data||!$prods){flash('Confira os campos e selecione origem, destino, transportador e ao menos um produto.','danger');redirect('frete_form.php');} try{$pdo->beginTransaction();$codigo='FR-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$s=$pdo->prepare('INSERT INTO fretes(codigo,origem_id,destino_id,transportador_id,data_frete,status,observacoes) VALUES(?,?,?,?,?,?,?)');$s->execute([$codigo,$origem,$destino,$trans,$data,$_POST['status']??'Pendente',trim($_POST['observacoes']??'')]);$freteId=(int)$pdo->lastInsertId();$link=$pdo->prepare('INSERT INTO frete_produtos(frete_id,produto_id,quantidade) VALUES(?,?,?)');foreach($prods as $i=>$pid){$pid=(int)$pid;$q=max(1,(int)($qtys[$i]??1));if($pid)$link->execute([$freteId,$pid,$q]);}$pdo->commit();flash("Frete $codigo gerado com sucesso.");redirect('fretes.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Erro ao gerar frete. Verifique os dados cadastrados.','danger');redirect('frete_form.php');}
